119	    /// Handle a key code event.
120	    ///
121	    /// Returns true if the key was handled.
122	    pub fn handle_key(&mut self, key_code: KeyCode) -> bool {
123	        handle_input(&mut self.text, &mut self.cursor, key_code);
124	        matches!(
125	            key_code,
126	            KeyCode::Char(_)
127	                | KeyCode::Backspace
128	                | KeyCode::Delete
129	                | KeyCode::Left
130	                | KeyCode::Right
131	                | KeyCode::Home
132	                | KeyCode::End
133	        )
134	    }
135	
136	    /// Handle an action from the keymap.
137	    ///
138	    /// Returns true if the action was handled.
139	    pub fn handle_action(&mut self, action: Action) -> bool {
140	        match action {
141	            Action::MoveLeft => {
142	                self.move_left();
143	                true
144	            }
145	            Action::MoveRight => {
146	                self.move_right();
147	                true
148	            }
149	            Action::Home => {
150	                self.move_home();
151	                true
152	            }
153	            Action::End => {
154	                self.move_end();
155	                true
156	            }
157	            Action::Backspace => {
158	                self.backspace();
159	                true
160	            }
161	            Action::DeleteChar => {
162	                self.delete();
163	                true
164	            }
165	            _ => false,
166	        }
167	    }
