1	//! Storage setup screen for configuring dotfiles storage.
2	//!
3	//! Provides a two-pane interface matching the settings screen pattern:
4	//! - Left: Storage method selection (GitHub or Local)
5	//! - Right: Form fields and context-sensitive help
6	
7	use crate::components::footer::Footer;
8	use crate::components::header::Header;
9	use crate::icons::Icons;
10	use crate::keymap::Action;
11	use crate::screens::screen_trait::{RenderContext, Screen, ScreenAction, ScreenContext};
12	use crate::styles::theme;
13	use crate::ui::{GitHubSetupData, GitHubSetupStep};
14	use crate::utils::{
15	    create_split_layout, create_standard_layout, focused_border_style, unfocused_border_style,
16	    MouseRegions, TextInput,
17	};
18	use crate::widgets::{Menu, MenuItem, MenuState, TextInputWidget, TextInputWidgetExt};
19	use anyhow::Result;
20	use crossterm::event::{Event, KeyEventKind, MouseButton, MouseEventKind};
21	use ratatui::layout::{Alignment, Constraint, Direction, Layout, Rect};
22	use ratatui::style::{Modifier, Style};
23	use ratatui::text::{Line, Span, Text};
24	use ratatui::widgets::{Block, Borders, Clear, Padding, Paragraph, StatefulWidget, Wrap};
25	use ratatui::Frame;
26	
27	/// Focus within the storage setup screen
28	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
29	pub enum StorageSetupFocus {
30	    #[default]
31	    MethodList, // Left pane - selecting storage method
32	    Form, // Right pane - editing form fields
33	}
34	
35	/// Selected storage method
36	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
37	pub enum StorageMethod {
38	    #[default]
39	    GitHub,
40	    Local,
41	}
42	
43	impl StorageMethod {
44	    fn all() -> Vec<StorageMethod> {
45	        vec![StorageMethod::GitHub, StorageMethod::Local]
46	    }
47	
48	    #[allow(dead_code)] // Utility method for potential future use
49	    fn name(&self) -> &'static str {
50	        match self {
51	            StorageMethod::GitHub => "GitHub Repository",
52	            StorageMethod::Local => "Local Repository",
53	        }
54	    }
55	
56	    fn index(&self) -> usize {
57	        match self {
58	            StorageMethod::GitHub => 0,
59	            StorageMethod::Local => 1,
60	        }
61	    }
62	
63	    fn from_index(index: usize) -> Option<StorageMethod> {
64	        match index {
65	            0 => Some(StorageMethod::GitHub),
66	            1 => Some(StorageMethod::Local),
67	            _ => None,
68	        }
69	    }
70	}
71	
72	/// GitHub form fields
73	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
74	pub enum GitHubField {
75	    #[default]
76	    Token,
77	    RepoName,
78	    RepoPath,
79	    Visibility,
80	}
81	
82	impl GitHubField {
83	    #[allow(dead_code)] // Utility method for potential future use
84	    fn all() -> Vec<GitHubField> {
85	        vec![
86	            GitHubField::Token,
87	            GitHubField::RepoName,
88	            GitHubField::RepoPath,
89	            GitHubField::Visibility,
90	        ]
91	    }
92	
93	    fn next(&self) -> GitHubField {
94	        match self {
95	            GitHubField::Token => GitHubField::RepoName,
96	            GitHubField::RepoName => GitHubField::RepoPath,
97	            GitHubField::RepoPath => GitHubField::Visibility,
98	            GitHubField::Visibility => GitHubField::Token,
99	        }
100	    }
101	
102	    fn prev(&self) -> GitHubField {
103	        match self {
104	            GitHubField::Token => GitHubField::Visibility,
105	            GitHubField::RepoName => GitHubField::Token,
106	            GitHubField::RepoPath => GitHubField::RepoName,
107	            GitHubField::Visibility => GitHubField::RepoPath,
108	        }
109	    }
110	}
111	
112	/// Current step in the storage setup process
113	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
114	pub enum StorageSetupStep {
115	    #[default]
116	    Input,
117	    /// GitHub setup state machine in progress
118	    Processing(GitHubSetupStep),
119	}
120	
121	/// Storage setup screen state
122	#[derive(Debug)]
123	pub struct StorageSetupState {
124	    // Focus and selection
125	    pub focus: StorageSetupFocus,
126	    pub method: StorageMethod,
127	    pub menu_state: MenuState,
128	
129	    // GitHub form fields
130	    pub token_input: TextInput,
131	    pub repo_name_input: TextInput,
132	    pub repo_path_input: TextInput,
133	    pub is_private: bool,
134	    pub github_field: GitHubField,
135	
136	    // Local form field
137	    pub local_path_input: TextInput,
138	
139	    // Status
140	    pub status_message: Option<String>,
141	    pub error_message: Option<String>,
142	
143	    // Configuration state
144	    pub is_reconfiguring: bool,
145	    pub is_editing_token: bool,
146	
