1	//! Profile selection screen controller.
2	//!
3	//! This screen handles profile selection after initial repository setup.
4	//! Users can select an existing profile or create a new one.
5	
6	use crate::config::Config;
7	use crate::screens::screen_trait::{RenderContext, Screen, ScreenAction, ScreenContext};
8	use crate::screens::ActionResult;
9	use crate::services::ProfileService;
10	use crate::styles::theme;
11	use crate::ui::{ProfileSelectionState, Screen as ScreenId};
12	use crate::utils::MouseRegions;
13	use crate::widgets::{DialogVariant, TextInputWidget, TextInputWidgetExt};
14	use anyhow::Result;
15	use crossterm::event::{Event, KeyCode, KeyEventKind, KeyModifiers, MouseButton, MouseEventKind};
16	use ratatui::layout::Rect;
17	use ratatui::prelude::*;
18	use ratatui::widgets::{Block, Borders, List, ListItem};
19	use ratatui::Frame;
20	use std::path::Path;
21	use tracing::{error, info};
22	
23	/// Actions that can be processed by the profile selection screen
24	#[derive(Debug, Clone)]
25	pub enum ProfileSelectionAction {
26	    /// Create a new profile and then activate it
27	    CreateAndActivateProfile { name: String },
28	    /// Activate an existing profile
29	    ActivateProfile { name: String },
30	}
31	
32	/// Profile selection screen controller.
33	pub struct ProfileSelectionScreen {
34	    state: ProfileSelectionState,
35	    /// Clickable regions for list items
36	    mouse_regions: MouseRegions<usize>,
37	    /// List pane area for scroll hit-testing
38	    list_area: Option<Rect>,
39	}
40	
41	impl ProfileSelectionScreen {
42	    /// Create a new profile selection screen.
43	    #[must_use]
44	    pub fn new() -> Self {
45	        Self {
46	            state: ProfileSelectionState::default(),
47	            mouse_regions: MouseRegions::new(),
48	            list_area: None,
49	        }
50	    }
51	
52	    /// Get the current state.
53	    #[must_use]
54	    pub fn get_state(&self) -> &ProfileSelectionState {
55	        &self.state
56	    }
57	
58	    /// Get mutable state.
59	    pub fn get_state_mut(&mut self) -> &mut ProfileSelectionState {
60	        &mut self.state
61	    }
62	
63	    /// Reset the screen state.
64	    pub fn reset(&mut self) {
65	        self.state = ProfileSelectionState::default();
66	    }
67	
68	    /// Set the profiles to select from.
69	    pub fn set_profiles(&mut self, profiles: Vec<String>) {
70	        self.state.profiles = profiles;
71	        if !self.state.profiles.is_empty() {
72	            self.state.list_state.select(Some(0));
73	        }
74	    }
75	
76	    /// Render the exit warning popup.
77	    fn render_exit_warning(&self, frame: &mut Frame, area: Rect, config: &Config) {
78	        use crate::widgets::{Dialog, DialogVariant};
79	
80	        let icons = crate::icons::Icons::from_config(config);
81	        let warning_text = format!(
82	            "{} Profile Selection Required\n\n\
83	            You MUST select a profile before continuing.\n\
84	            Activating a profile will replace your current dotfiles with symlinks.\n\
85	            This action cannot be undone without restoring from backups.\n\n\
86	            Please select a profile or create a new one.\n\
87	            Press Esc again to cancel and return to main menu.",
88	            icons.warning()
89	        );
90	
91	        let footer_text = format!(
92	            "{}: Cancel & Return to Main Menu",
93	            config
94	                .keymap
95	                .get_key_display_for_action(crate::keymap::Action::Cancel)
96	        );
97	
98	        let dialog = Dialog::new("Warning", &warning_text)
99	            .height(35)
100	            .variant(DialogVariant::Warning)
101	            .footer(&footer_text);
102	        frame.render_widget(dialog, area);
103	    }
104	
105	    /// Render the create profile popup.
106	    fn render_create_popup(&mut self, frame: &mut Frame, area: Rect, config: &Config) {
107	        use crate::components::Popup;
108	
109	        let footer_text = format!(
110	            "{}: Create  |  {}: Cancel",
111	            config
112	                .keymap
113	                .get_key_display_for_action(crate::keymap::Action::Confirm),
114	            config
115	                .keymap
116	                .get_key_display_for_action(crate::keymap::Action::Cancel)
117	        );
118	
119	        let Some(result) = Popup::new()
120	            .width(50)
121	            .height(12)
122	            // 3 (input) + borders/title/footer (~5) = 8.
123	            .min_height(8)
124	            .min_width(40)
125	            .title("Create New Profile")
126	            .dim_background(true)
127	            .footer(&footer_text)
128	            .render(frame, area)
129	        else {
130	            return;
131	        };
132	
133	        let widget = TextInputWidget::new(&self.state.create_name_input)
134	            .title("Profile Name")
135	            .placeholder("Enter profile name...")
136	            .focused(true);
137	
138	        frame.render_text_input_widget(widget, result.content_area);
139	    }
140	
141	    /// Render the main profile list.
142	    fn render_profile_list(&mut self, frame: &mut Frame, area: Rect, config: &Config) {
143	        use crate::components::footer::Footer;
144	        use crate::components::header::Header;
145	        use crate::styles::LIST_HIGHLIGHT_SYMBOL;
146	        use crate::utils::create_standard_layout;
147	
148	        let icons = crate::icons::Icons::from_config(config);
149	        let (header_area, content_area, footer_area) = create_standard_layout(area, 5, 3);
150	
151	        // Track mouse regions
152	        self.list_area = Some(content_area);
153	        self.mouse_regions.clear();
154	        let inner = Block::default().borders(Borders::ALL).inner(content_area);
155	        let total_items = self.state.profiles.len() + 1; // +1 for "Create New"
156	        let scroll_offset = self.state.list_state.offset();
157	        for i in 0..total_items {
158	            let visible_idx = i.saturating_sub(scroll_offset);
159	            if i >= scroll_offset && (visible_idx as u16) < inner.height {
160	                let row = Rect::new(inner.x, inner.y + visible_idx as u16, inner.width, 1);
161	                self.mouse_regions.add(row, i);
162	            }
163	        }
164	
165	        // Header
166	        let _ = Header::render(
167	            frame,
168	            header_area,
169	            "Select Profile to Activate",
170	            "Choose which profile to activate after setup",
171	        );
172	
173	        // Build list items
174	        let mut items: Vec<ListItem> = self
175	            .state
176	            .profiles
177	            .iter()
178	            .map(|name| ListItem::new(format!("  {name}")))
179	            .collect();
180	
181	        // Add "Create New Profile" option
182	        items.push(
183	            ListItem::new(format!("  {} Create New Profile", icons.create()))
184	                .style(Style::default().fg(Color::Cyan)),
185	        );
186	
187	        let list = List::new(items)
188	            .block(
189	                Block::default()
190	                    .title(" Available Profiles ")
191	                    .borders(Borders::ALL)
192	                    .border_type(theme().border_type(false)),
193	            )
194	            .highlight_style(
195	                Style::default()
196	                    .add_modifier(Modifier::BOLD)
197	                    .fg(Color::Cyan),
198	            )
199	            .highlight_symbol(LIST_HIGHLIGHT_SYMBOL);
